  [1462] = { "Raccoglie informazioni sulla bestia bersaglio. Il tooltip mostrerà danni, salute, armatura, eventuali resistenze speciali e dieta.", "Conoscenza rivelata.", 0x4707687a, 0xe667adde, "uu" },
  [1463] = { "Assorbe $N1 danni fisici, prosciugando mana al loro posto. Prosciuga $N2 mana per ogni danno assorbito. Dura $D1.", "Assorbe i danni fisici, prosciugando mana al loro posto.", 0x6186eef7, 0xd9625b22, "uu" },
  [1464] = { "Colpisce l'avversario, infliggendo i danni dell'arma e $N1 danni aggiuntivi.", nil, 0x27b9eb8b, nil, "um" },
  [1494] = { "Indica sulla minimappa la posizione delle bestie vicine. Può essere attiva una sola forma di tracciamento alla volta.", "Bestie individuate.", 0x7a0f6d82, 0x5bdf0ba6, "uu" },
  [1495] = { "Contrattacca il nemico, infliggendo i danni dell'arma da mischia e $N1 danni aggiuntivi. Utilizzabile solo dopo aver schivato.", nil, 0xb7f0fcdf, nil, "um" },
  [1499] = { "Piazza una trappola di gelo che congela il primo nemico che si avvicina, impedendogli qualsiasi azione per un massimo di $D1. Qualsiasi danno inflitto spezza il ghiaccio. La trappola dura $D2. Può essere attiva una sola trappola di gelo alla volta.", nil, 0xe57bc3d9, nil, "um" },
  [1510] = { "Scaglia continuamente una raffica di munizioni sull'area bersaglio, infliggendo $N1 danni da arcano ai nemici entro $N2 m ogni $D1 per $D2.", nil, 0x7756797c, nil, "um" },
  [1513] = { "Spaventa una bestia, costringendola a fuggire per un massimo di $D1. Eventuali danni inflitti al bersaglio potrebbero interrompere l'effetto. Può essere spaventata solo una bestia alla volta.", "Impaurito.", 0xcc6a4f70, 0x5a2205f2, "uu" },
  [1515] = { "Inizia ad addomesticare una bestia perché diventi tua compagna. La tua armatura è ridotta del $N1% mentre ti concentri sull'addomesticamento della bestia per $D1. Se per qualsiasi motivo perdi l'attenzione della bestia, l'addomesticamento fallisce. Una volta addomesticata, la bestia sarà molto infelice e sleale. Prova a nutrire subito il famiglio per renderlo felice.", "Addomesticamento del famiglio.", 0x653847d0, 0xc7d3fce8, "uu" },
  [1528] = { "Libera il padrone da qualsiasi impedimento.", nil, 0x4e68a849, nil, "um" },
