  [1671] = { "Colpisce il bersaglio con lo scudo, infliggendo $N1 danni. Inoltre interrompe il lancio di incantesimi e impedisce di lanciare qualsiasi incantesimo di quella scuola per $D1.", nil, 0x7e95b69c, nil, "um" },
  [1672] = { "Colpisce il bersaglio con lo scudo, infliggendo $N1 danni. Inoltre interrompe il lancio di incantesimi e impedisce di lanciare qualsiasi incantesimo di quella scuola per $D1.", nil, 0x7e95b69c, nil, "um" },
  [1680] = { "In un turbine d'acciaio attacchi fino a un massimo di $N1 nemici entro $N2 m, infliggendo a ciascuno i danni di entrambe le armi da mischia.", nil, 0x0013ad56, nil, "um" },
  [1706] = { "Permette all'incantatore di levitare a poca distanza da terra. In questo stato, si cade a una velocità ridotta e si può camminare sulle superfici d'acqua. Salire su una cavalcatura o subire danni annulla l'effetto. Dura $D1.", "In levitazione.", 0x2714f771, 0xfb3d5081, "uu" },
