  [1719] = { "Il Guerriero ottiene il $N1% di probabilità di critico in più e diventa immune agli effetti di paura per $D1, ma tutti i danni subiti aumentano del $N3%.", "Immune agli effetti di paura, probabilità di critico aumentata del $N1%, ma tutti i danni subiti aumentati del $N2%.", 0x2a57cc08, 0x526ed478, "uu" },
