  [1735] = { "Il Druido ruggisce, riducendo di $N1 la potenza d'attacco in mischia dei nemici vicini. Dura $D1.", "Potenza d'attacco in mischia ridotta di $N1.", 0x79835d42, 0x5069052b, "uu" },
